//! Object storage (S3-compatible, R2). Keys are generated by the server under a tenant
//! prefix; callers never choose them.

use crate::Result;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PresignRequest {
    pub key: String,
    pub content_type: Option<String>,
    /// Upload size limit, enforced in the presign conditions.
    pub max_bytes: u64,
    pub ttl_seconds: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Presigned {
    pub url: String,
    pub method: String,
    pub headers: Vec<(String, String)>,
    pub expires_at_micros: i64,
}

pub trait ObjectStore {
    async fn presign_upload(&self, request: PresignRequest) -> Result<Presigned>;
    async fn presign_download(&self, request: PresignRequest) -> Result<Presigned>;
}
